// Generated by vibekit. Do not edit.
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const SKILLS = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../skills')
const LIST = [
  {"name":"brainstorm","description":"Use when quick's gate trips and the user picks the normal flow, or when vibe or repl hands off an intent. Hard gate, no code before an approved design."},
  {"name":"debug","description":"Use when a check fails: a red test, a broken build, a failed clause, or a bug you can point at. Finds a root cause and gets it refuted before anything is fixed. Diagnosis is the product. This skill never edits."},
  {"name":"decide","description":"Loaded by repl or quick: answers every question a skill would put to the user during a run without the user. Settled answers are followed, one-way doors pause, experiments settle what they can, and two-way doors are decided and logged."},
  {"name":"exec","description":"Use when a plan is approved and implementation has not started: dispatches one fresh subagent per task, runs each task's verify clause, and routes failures back instead of repairing them. One task, one commit."},
  {"name":"lazy","description":"Use at the start of any coding work: writing, adding, refactoring, fixing, designing. The laziness ladder, stdlib and native features before new code, one line before fifty. Stays on after."},
  {"name":"plain","description":"Use before writing any text, in chat or into a file. Thirteen rules that hold in every string you emit, including code comments, commit messages, PR bodies and docs. No em dash, no semicolon, no hard wrapping inside a paragraph, no curly quotes, no decorative emoji, no title case in headings, no bold label lists, no heading echo, no fragment runs, no padded triads, no rejected straw options, no unraised objections, no writing about the previous version. Stays on after."},
  {"name":"plan","description":"Use when a spec is approved and implementation has not started: turns it into a task-by-task plan with exact paths and checkable verification. No code here."},
  {"name":"quick","description":"Use before any implementation work: features, fixes, behavior changes. Checks the size first, then thinks the design through silently, builds in one go and proves it works by running it. Asks the user to move big work to the normal flow or repl."},
  {"name":"repl","description":"Use when the user types /vibekit:repl: brainstorms and plans without the user, shows a plain summary and waits for a go, then carries exec, verify and debug to the end with no human input, deciding by decide's rules and stopping only for what the user alone can decide."},
  {"name":"retro","description":"Use when a run ended and a debug report in it carried a Class: other than none, or when the user types /vibekit:retro: looks back over this session's failures and friction, proposes checks and rules that would catch them next time, and writes only what the user picks."},
  {"name":"terse","description":"Use at the start of every session. Compress narration, never artifacts. Questions, evidence, specs, plans and warnings stay verbatim. Stays on after."},
  {"name":"using-vibekit","description":"Use when starting any conversation: establishes the auto-trigger discipline so guardrail skills fire instead of being silently skipped."},
  {"name":"verify","description":"Use before claiming a change is done, fixed or passing: checks the whole change against its spec, runs the checks no single task could, hunts for the bugs the change produced, and returns ready or not ready. Evidence or it did not happen."},
  {"name":"vibe","description":"Run a short intent through the pipeline. Invoked as /vibekit:vibe. Hands off to brainstorm and does nothing else."},
]
const BOOTSTRAP = "using-vibekit"
const PIPELINE = ["brainstorm","debug","exec","plan","quick","repl","retro","verify","vibe"]
const MODIFIERS = ["lazy","plain","terse"]
const missingSkills = (loaded, pipeline, modifiers) => [
  ...(pipeline.some(name => loaded.has(name)) ? [] : ['quick']),
  ...modifiers.filter(name => !loaded.has(name)),
]
const denyReason = missing => 'vibekit denied this edit, so the file was not changed. Load each of these vibekit skills first, in order:' + missing.map(name => ' vibekit:' + name).join('') + '. Then retry the edit. Retrying first is denied again. To turn this check off, set VIBEKIT_GATE=off.'
const startText = (name, body) => '<EXTREMELY_IMPORTANT>\nYou have vibekit.\n\nBelow is the full content of the ' + name + ' skill. Load every other vibekit skill the way this tool loads skills.\n\n' + body + '\n</EXTREMELY_IMPORTANT>'

function body(name) {
  return readFileSync(path.join(SKILLS, name, 'SKILL.md'), 'utf8').replace(/^---\r?\n[\s\S]*?\r?\n---(?:\r?\n)?/, '')
}

export default {
  id: "vibekit",
  setup: async ctx => {
    await ctx.skill.transform(draft => {
      for (const { name, description } of LIST) {
        draft.add({ id: name, name, description, path: path.join(SKILLS, name, 'SKILL.md'), content: body(name) })
      }
    })

    const loaded = new Map()
    const mark = (sessionID, name) => {
      if (!loaded.has(sessionID)) loaded.set(sessionID, new Set())
      loaded.get(sessionID).add(name)
    }

    let start = ''
    try {
      start = startText(BOOTSTRAP, body(BOOTSTRAP))
    } catch {}
    if (start) {
      await ctx.session?.hook?.('context', async context => {
        context.system.push({ type: 'text', text: start })
      })
    }

    // The model loads a skill through the skill tool. A skill the user
    // starts directly arrives as a session.skill.activated event instead.
    await ctx.tool?.hook?.('execute.after', async event => {
      if (event.tool === 'skill' && event.status === 'completed' && event.input?.id) mark(event.sessionID, event.input.id)
    })
    const events = ctx.event?.subscribe?.()
    if (events) {
      ;(async () => {
        try {
          for await (const event of events) {
            if (event?.type !== 'session.skill.activated') continue
            const data = event.properties ?? event
            if (data.sessionID && data.id) mark(data.sessionID, data.id)
          }
        } catch {}
      })()
    }

    // A session with a parentID is a subagent, dispatched by a stage that
    // already passed the guard.
    await ctx.permission?.hook?.('evaluate', async event => {
      if (event.action !== 'edit' || process.env.VIBEKIT_GATE === 'off') return
      try {
        const session = await ctx.session.get({ sessionID: event.sessionID })
        if (session?.parentID) return
        const missing = missingSkills(loaded.get(event.sessionID) ?? new Set(), PIPELINE, MODIFIERS)
        if (missing.length) {
          event.effect = 'deny'
          event.message = denyReason(missing)
        }
      } catch {}
    })
  },
}
